CREATE   PROCEDURE [synapse_ce].[usp_Update_apuk_assessmentevent]
AS
BEGIN
	UPDATE tgt SET 
		tgt.[apuk_applicationtype] = stg.[apuk_applicationtype],
		tgt.[apuk_applicationtypeid] = stg.[apuk_applicationtypeid],
		tgt.[apuk_applicationtypeid_entitytype] = stg.[apuk_applicationtypeid_entitytype],
		tgt.[apuk_applicationtypeidname] = stg.[apuk_applicationtypeidname],
		tgt.[apuk_assessmentapplicationwindowid] = stg.[apuk_assessmentapplicationwindowid],
		tgt.[apuk_assessmentapplicationwindowid_entitytype] = stg.[apuk_assessmentapplicationwindowid_entitytype],
		tgt.[apuk_assessmentapplicationwindowidname] = stg.[apuk_assessmentapplicationwindowidname],
		tgt.[apuk_assessmenteventid] = stg.[apuk_assessmenteventid],
		tgt.[apuk_assessmentvenue] = stg.[apuk_assessmentvenue],
		tgt.[apuk_assessmentvenue_entitytype] = stg.[apuk_assessmentvenue_entitytype],
		tgt.[apuk_assessmentvenuename] = stg.[apuk_assessmentvenuename],
		tgt.[apuk_dayfivedate] = stg.[apuk_dayfivedate],
		tgt.[apuk_dayfourdate] = stg.[apuk_dayfourdate],
		tgt.[apuk_dayonedate] = stg.[apuk_dayonedate],
		tgt.[apuk_daysixdate] = stg.[apuk_daysixdate],
		tgt.[apuk_daythreedate] = stg.[apuk_daythreedate],
		tgt.[apuk_daytwodate] = stg.[apuk_daytwodate],
		tgt.[apuk_electiondate] = stg.[apuk_electiondate],
		tgt.[apuk_firstchoicecompletedon] = stg.[apuk_firstchoicecompletedon],
		tgt.[apuk_firstchoicestartedon] = stg.[apuk_firstchoicestartedon],
		tgt.[apuk_locationid] = stg.[apuk_locationid],
		tgt.[apuk_locationid_entitytype] = stg.[apuk_locationid_entitytype],
		tgt.[apuk_locationidname] = stg.[apuk_locationidname],
		tgt.[apuk_name] = stg.[apuk_name],
		tgt.[apuk_noofrooms1] = stg.[apuk_noofrooms1],
		tgt.[apuk_noofrooms2] = stg.[apuk_noofrooms2],
		tgt.[apuk_noofrooms3] = stg.[apuk_noofrooms3],
		tgt.[apuk_noofrooms4] = stg.[apuk_noofrooms4],
		tgt.[apuk_noofrooms5] = stg.[apuk_noofrooms5],
		tgt.[apuk_noofrooms6] = stg.[apuk_noofrooms6],
		tgt.[apuk_secondchoicecompletedon] = stg.[apuk_secondchoicecompletedon],
		tgt.[apuk_secondchoicestartedon] = stg.[apuk_secondchoicestartedon],
		tgt.[apuk_thirdchoicecompletedon] = stg.[apuk_thirdchoicecompletedon],
		tgt.[apuk_thirdchoicestartedon] = stg.[apuk_thirdchoicestartedon],
		tgt.[apuk_whatshappening] = stg.[apuk_whatshappening],
		tgt.[createdby] = stg.[createdby],
		tgt.[createdby_entitytype] = stg.[createdby_entitytype],
		tgt.[createdbyname] = stg.[createdbyname],
		tgt.[createdbyyominame] = stg.[createdbyyominame],
		tgt.[createdon] = stg.[createdon],
		tgt.[createdonbehalfby] = stg.[createdonbehalfby],
		tgt.[createdonbehalfby_entitytype] = stg.[createdonbehalfby_entitytype],
		tgt.[createdonbehalfbyname] = stg.[createdonbehalfbyname],
		tgt.[createdonbehalfbyyominame] = stg.[createdonbehalfbyyominame],
		tgt.[importsequencenumber] = stg.[importsequencenumber],
		tgt.[modifiedby] = stg.[modifiedby],
		tgt.[modifiedby_entitytype] = stg.[modifiedby_entitytype],
		tgt.[modifiedbyname] = stg.[modifiedbyname],
		tgt.[modifiedbyyominame] = stg.[modifiedbyyominame],
		tgt.[modifiedon] = stg.[modifiedon],
		tgt.[modifiedonbehalfby] = stg.[modifiedonbehalfby],
		tgt.[modifiedonbehalfby_entitytype] = stg.[modifiedonbehalfby_entitytype],
		tgt.[modifiedonbehalfbyname] = stg.[modifiedonbehalfbyname],
		tgt.[modifiedonbehalfbyyominame] = stg.[modifiedonbehalfbyyominame],
		tgt.[organizationid] = stg.[organizationid],
		tgt.[organizationid_entitytype] = stg.[organizationid_entitytype],
		tgt.[organizationidname] = stg.[organizationidname],
		tgt.[overriddencreatedon] = stg.[overriddencreatedon],
		tgt.[SinkCreatedOn] = stg.[SinkCreatedOn],
		tgt.[SinkModifiedOn] = stg.[SinkModifiedOn],
		tgt.[statecode] = stg.[statecode],
		tgt.[statuscode] = stg.[statuscode],
		tgt.[timezoneruleversionnumber] = stg.[timezoneruleversionnumber],
		tgt.[utcconversiontimezonecode] = stg.[utcconversiontimezonecode],
		tgt.[versionnumber] = stg.[versionnumber]
	 FROM [synapse_ce].[apuk_assessmentevent] tgt
		INNER JOIN [staging_ce].[apuk_assessmentevent] stg
			ON tgt.[id] = stg.[id]
END
